-- ============================================================
-- 3DMP Service · 0180_help_packs.sql  (план v3, W37 «Документация/мануалы»)
-- Встроенная справка: паки базы знаний (категории «Справка» и «Администрирование»).
-- Дополняет docs/USER_GUIDE.md и docs/ADMIN_GUIDE.md. Идемпотентно. Зависит от 0001..0179.
-- ============================================================

insert into public.app_knowledge (tenant_id, category, question, answer, tags)
select 'aaaaaaaa-0000-0000-0000-000000000001', v.category, v.question, v.answer, v.tags
from (values
  ('Справка','Как начать работу: вход, кабинет, хаб',
   'Откройте https://sapfir.eu/saas/ → «Вход» (логин/пароль выдаёт администратор; демо: admin/admin, owner/owner, manager/manager, master/master, qc/otk, supply/supply, support/support, client2/client2). После входа — «Личный кабинет» и «Хаб» (каталог модулей). Сессия хранится в браузере; выход — кнопка «Выйти».',
   'старт вход кабинет хаб справка'),
  ('Справка','Хаб и каталог модулей: группы, поиск, избранное',
   'Хаб показывает все доступные модули плитками, сгруппированными по контурам (Ядро, Продажи, КТПП, Производство, Качество, Экономика, Персонал, Платформа, Референсы). Есть поиск, фильтр-чипы по контурам и «⭐ Избранное» (звёздочка на плитке), блок «🕘 Недавние», «⚡ Быстрый доступ» и режимы «Обычный/Компактно». Группы сворачиваются кликом по заголовку. Глубокие ссылки: #group/<id>, #app/<id>, #fav.',
   'хаб каталог группы поиск фильтр избранное недавние компактный справка'),
  ('Справка','Навигация: кнопка «Назад» и хлебные крошки',
   'В каждом модуле в шапке есть кнопка «← Назад» (возвращает к предыдущему экрану; если истории нет — к группе модуля в Хабе) и хлебные крошки «🏠 Каталог › Группа › Модуль». Возврат в Хаб — «🏠 Каталог». Позиция прокрутки Хаба сохраняется.',
   'навигация назад крошки хлебные каталог группа справка'),
  ('Справка','Мобильный режим и установка приложения (PWA)',
   'На телефоне откройте модуль — внизу появится панель быстрых действий (или включите режим кнопкой 📱, параметр URL mobile=1). Крупные тач-кнопки, скрытие второстепенного. Сервис — PWA: «Добавить на главный экран». Часть действий (напр. измерение ОТК) сохраняется офлайн и отправится при восстановлении связи.',
   'мобильный телефон pwa установка офлайн быстрые действия справка'),
  ('Справка','Быстрые мастера: НСИ, инструмент, приёмка, процесс, КЭДО, перевозка',
   'Мастера проводят по шагам (с валидацией и черновиком): позиция НСИ, экземпляр инструмента, приёмка на склад, запуск процесса, кадровый документ, заявка на перевозку. Кнопка «＋ … (мастер)» — в соответствующих модулях (или на мобильной панели). Черновик сохраняется в браузере — можно продолжить позже.',
   'мастера wizard нси инструмент приёмка склад процесс кэдо перевозка черновик справка'),
  ('Справка','Отчёты и выгрузки (PDF/DOC/CSV/JSON)',
   'В модуле — кнопка «📄 Отчёт» (PDF/CSV по данным модуля). Раздел «Отчёты и экспорт»: наборы данных (заявки, наряды, закупки, склад, ОТК, маршруты + наборы новых модулей: НСИ, PLM, ЭДО, КЭДО, EAM, EHS, холдинг, сметы, PMO, TMS, ITSM, обучение, бухгалтерия, задачи, CRM), конструктор сохранённых отчётов (колонки/фильтры/группировка/график) и «Дашборд новых модулей».',
   'отчёты экспорт pdf doc csv json конструктор дашборд bi справка'),
  ('Администрирование','Расширения и маркетплейс: установка по тенанту',
   'Модуль «Маркетплейс» → вкладка «Расширения»: каталог манифестов (коннектор/шаблон/отчёт/набор данных/БЗ/виджет). Установка — администратор/владелец организации; включение коннектора подтягивает точку интеграции в «Интеграции». Создание/правка манифеста — администратор платформы. Все действия пишутся в журнал.',
   'расширения маркетплейс extensions установка тенант коннектор интеграции аудит'),
  ('Администрирование','Мониторинг доступности и алерты',
   'Модуль «Диагностика» → блок «Мониторинг доступности»: KPI в норме/предупреждения/сбои, тренд доступности за 14 дней, открытые алерты. «Проверить сейчас» запускает app_health_scan (проверяет БД, таблицы, функции, Realtime, интеграции, счета, «свежесть данных» и внешние пинги). Внешний uptime — app_health_ping(API-ключ). Алерты дедуплицируются (kind:name), при сбое уведомляются администраторы платформы, при норме — закрываются автоматически (или вручную).',
   'мониторинг доступность sla алерты health ping тренд диагностика'),
  ('Администрирование','Регулярные проверки: run-checks и расписание',
   'Проверки: tools\\run-checks.ps1 (audit + db-smoke, лог в dist/checks/, код возврата 0/1). Расписание: Windows Task Scheduler (powershell -NoProfile -ExecutionPolicy Bypass -File tools\\run-checks.ps1 -Token sbp_...) или CI .github/workflows/checks.yml (ежедневно, секрет SUPABASE_ACCESS_TOKEN). Без токена — только локальный аудит (-SkipDb — пропустить БД).',
   'проверки run-checks расписание ci task scheduler audit db-smoke'),
  ('Администрирование','Роли, права и видимость модулей',
   'Роли: admin, owner, manager, director, chief, master, technologist, operator, supply, qc, economist, support, supplier, client. Видимость модуля — поле roles в каталоге; внутри модуля — data-cap/CAPS (client/supplier/guest скрывают редактирование). Гибкие права (наборы/делегирование) — «Права и согласования» (apps/access), учёт через app_can. Гейтинг по подразделению — apps/org.',
   'роли права доступ data-cap caps app_can подразделение видимость'),
  ('Администрирование','Интеграции, API-ключи и вебхуки',
   '«Интеграции» (apps/integrations) — каналы e-mail/Telegram/SMS/ЭДО/webhook через очередь app_integrations (воркер backend-example). «API и интеграции» (apps/api) — API-ключи (app_api_key_*), вебхуки, лог вызовов, подписи (ПЭП/УНЭП/УКЭП/Госключ), проверка контрагентов. Внешний мониторинг использует app_health_ping по API-ключу.',
   'интеграции api ключи вебхуки webhook очередь воркер подписи'),
  ('Администрирование','Деплой, миграции и бэкапы',
   'Сборка: tools\\build-release.ps1 → dist\\saas-<дата>.zip. Заливка (FTP) в sapfir.eu\\saas: index.html, apps/, assets/, eco/, web.config, manifest.webmanifest, sw.js (НЕ льются supabase/, docs/, tools/, dist/, .git). После заливки — Ctrl+F5. Миграции: supabase/migrations/NNNN_*.sql (или apply_all.sql) через SQL Editor / Management API (UTF-8, идемпотентно); после — db-smoke. Бэкапы — средствами Supabase; секреты — только в vault/CI.',
   'деплой ftp миграции бэкап apply_all релиз секреты')
) as v(category,question,answer,tags)
where not exists (
  select 1 from public.app_knowledge k
   where k.tenant_id = 'aaaaaaaa-0000-0000-0000-000000000001' and k.question = v.question
);
